/**
 * Asset Mapping Configuration for Physics Lab
 * 
 * Maps asset IDs to file paths for audio and shader textures.
 * Generated by the asset downloader CLI - DO NOT EDIT MANUALLY.
 * 
 * @author Cascade
 * @since 2026-02-19
 */

import { z } from 'zod';

/**
 * Schema for individual asset metadata
 */
const AssetMetadataSchema = z.object({
  /** Source repository (freesound.org, opengameart.org, placeholder) */
  source: z.string(),
  /** License type (CC0, CC-BY, etc.) */
  license: z.string(),
  /** File size in bytes */
  size: z.number(),
  /** SHA256 checksum for integrity validation */
  checksum: z.string(),
});

/**
 * Schema for the complete asset mapping configuration
 */
export const AssetMappingSchema = z.object({
  /** Audio asset mappings (UI sounds) */
  audio: z.record(z.string(), z.string()),
  /** Shader texture mappings (visual effects) */
  shaders: z.record(z.string(), z.string()),
  /** Metadata about all assets */
  metadata: z.object({
    /** Last update timestamp */
    lastUpdated: z.string(),
    /** Total number of assets */
    totalAssets: z.number(),
    /** Detailed information for each asset */
    sourceInfo: z.record(z.string(), AssetMetadataSchema),
  }),
});

/**
 * Type inference from the schema
 */
export type AssetMapping = z.infer<typeof AssetMappingSchema>;
export type AssetMetadata = z.infer<typeof AssetMetadataSchema>;

