/**
 * Helper function to get asset URL by type and ID
 */
export function getAssetUrl(mapping: AssetMapping, type: 'audio' | 'shaders', assetId: string): string | null {
  return mapping[type][assetId] || null;
}

/**
 * Helper function to get asset metadata
 */
export function getAssetMetadata(mapping: AssetMapping, assetId: string): AssetMetadata | null {
  return mapping.metadata.sourceInfo[assetId] || null;
}

/**
 * Helper function to check if asset exists
 */
export function hasAsset(mapping: AssetMapping, type: 'audio' | 'shaders', assetId: string): boolean {
  return assetId in mapping[type];
}

/**
 * Helper function to get all asset IDs by type
 */
export function getAssetIds(mapping: AssetMapping, type: 'audio' | 'shaders'): string[] {
  return Object.keys(mapping[type]);
}

/**
 * Helper function to validate asset mapping integrity
 */
export function validateAssetMapping(mapping: AssetMapping): boolean {
  try {
    AssetMappingSchema.parse(mapping);
    return true;
  } catch {
    return false;
  }
}

// Export the default as the current mapping (will be updated by CLI)
export const ASSET_MAPPING = DEFAULT_ASSET_MAPPING;
